type Add = (domain: string, passage: string, prompt: string, answer: string, wrong: string[], explanation: string) => void;
const cs="Craft and Structure", ii="Information and Ideas", se="Standard English Conventions", ec="Expression of Ideas";
const conventions = "Which choice completes the text so that it conforms to the conventions of Standard English?";
const transition = "Which choice completes the text with the most logical transition?";
const notesPrompt = (goal: string) => `While researching a topic, a student has taken the notes above. The student wants to ${goal}. Which choice most effectively uses relevant information from the notes to accomplish this goal?`;

/** Module 1: the original 27 items, with sentence-initial capitals and distractors as long as the key. */
function firstReading(c: Context, paper: number, add: Add) {
  add(cs,`At ${c.place}, ${c.subject} described its early results as provisional. Although ${c.measure} improved after ${c.intervention}, the team planned further comparisons before making a general recommendation.`,"As used in the text, 'provisional' most nearly means", "subject to later revision",["kept from other researchers","accepted by every reviewer","too expensive to repeat"],"The planned further comparisons show the results are tentative rather than final.");
  add(cs,`${cap(c.subject)} examined ${c.object} at ${c.place}. Instead of treating every difference as meaningful, the researchers distinguished persistent changes from fluctuations that disappeared on repeat measurement.`,"The text primarily emphasises the importance of", "separating reproducible patterns from temporary variation",["treating the largest single change as the most reliable evidence","accepting the largest observed change without question","using only observations that support an initial belief"],"The contrast is between persistent changes and fluctuations that fail to recur.");
  add(cs,`Text 1: ${cap(c.intervention)} could produce ${c.benefit}, but a single trial is insufficient evidence for widespread adoption.\nText 2: A trial at ${c.place} showed improved ${c.measure}; however, ${c.limitation}, making a controlled follow-up necessary.`,"How would the author of Text 2 most likely respond to Text 1?","By offering a case illustrating the need for further evidence",["By rejecting the possibility of any benefit","By insisting that the first trial already proves the benefit everywhere","By arguing that controlled comparisons have no value"],"Both texts support caution; the second supplies a specific confounding factor.");
  add(cs,`A report on ${c.object} begins with the reasons for ${c.intervention}. It then describes measurements at ${c.place}, before considering whether alternative explanations could account for the findings.`,"Which best describes the report's organisation?","A rationale is followed by evidence and an assessment of its interpretation",["An objection is dismissed without supporting evidence","A prediction is stated, tested at several sites, and then confirmed without any reservations","A final conclusion is repeated without analysis"],"The sequence is reasons, measurements, then alternative interpretations.");
  add(cs,`The increase in ${c.measure} was modest, but it persisted in several repeat observations at ${c.place}. The researchers considered this consistency more informative than one unusually large increase.`,"As used in the text, 'modest' most nearly means","limited in size",["unwilling to speak","impossible to measure","morally admirable"],"The text contrasts a small persistent increase with one unusually large increase.");
  add(cs,`${cap(c.subject)} welcomed the possibility of ${c.benefit}. Nevertheless, its report noted that ${c.limitation}.`,"What is the function of the second sentence?","To qualify an encouraging interpretation by identifying a limitation",["To establish that the intervention was never attempted","To show that the encouraging interpretation was later confirmed by every measurement","To replace the study with a personal anecdote"],"'Nevertheless' introduces a caveat to the positive prospect.");
  add(cs,`An observer at ${c.place} called the records of ${c.object} 'a conversation with the next investigator'. The records preserved unsuccessful attempts as carefully as promising ones.`,"The metaphor chiefly suggests that the records", "help later researchers build on earlier experience",["make later observations unnecessary for anyone studying the site","contain only spoken testimony","conceal the methods used by the original team"],"Preserving both successes and failures gives future investigators usable context.");
  const before=20+paper*2, after=before+8;
  add(ii,`Illustrative study at ${c.place}: the index of ${c.measure} was ${before} before ${c.intervention} and ${after} afterward. The index was measured in the same units on both occasions.`,"Which statement is directly supported by these data?",`The measured index increased by ${after-before} units`,[`The index doubled`,`The index increased because of the intervention alone`,`The index was unchanged`],`${after} − ${before} = ${after-before}. These data alone do not explain the cause.`);
  add(ii,`After ${c.intervention}, ${c.measure} increased at ${c.place}. However, ${c.limitation}.`,"Which additional evidence would best help isolate the intervention's effect?","Measurements from comparable untreated units observed over the same period",["A description of the researchers' preferred outcome","Measurements of the treated units repeated later by the same researchers using the same method","A list of unrelated projects in another field"],"Comparable untreated units help distinguish intervention effects from background changes.");
  add(ii,`${cap(c.subject)} randomly assigned comparable ${c.object} to treatment and control conditions, kept measurement methods constant, and repeated observations.`,"Which feature most directly reduces systematic pre-existing differences between conditions?","Random assignment",["The length of the report's title","The use of a single publication venue","The researchers' interest in a positive result"],"Random assignment reduces systematic selection differences; it does not guarantee identical groups.");
  add(ii,`At ${c.place}, a study of ${c.object} found promising changes after ${c.intervention}. The investigators noted that only one location and one season had been examined.`,"Which conclusion is most defensible?","The findings warrant further tests in other settings",["The intervention must work everywhere","Seasonal conditions are irrelevant","The study establishes that every alternative is inferior"],"The limited setting supports further investigation rather than universal claims.");
  add(ii,`Some observers proposed replacing all existing procedures with ${c.intervention}. ${cap(c.subject)} instead recommended a small extension of the trial while collecting the same measures in untreated areas.`,"Which inference is best supported?","The team regarded the evidence as promising but insufficient for complete replacement",["The team believed the evidence already justified replacing every existing procedure at once","The untreated areas had already received the intervention","The intervention had been conclusively disproved"],"A limited extension with controls indicates cautious interest, not complete acceptance or rejection.");
  add(ii,`A hypothesis predicts that ${c.intervention} will improve ${c.measure} even when background conditions are held constant.`,"Which finding would most directly weaken the hypothesis?","Repeated controlled trials show no improvement in the treated units relative to controls",["Treated units improve in one trial, while the controls in that trial are not measured at all","The researchers collect data on several days","A report explains why the outcome matters"],"Repeated absence of the predicted relative improvement directly challenges the hypothesis.");
  add(ii,`${cap(c.subject)} found that successful ${c.object} were not distributed evenly across ${c.place}. Some areas showed substantial improvement while others changed little.`,"Which summary best preserves the qualification in the text?","Outcomes varied within the study location",["Every unit improved by the same amount","No unit showed improvement","The study compared every possible location"],"The central contrast is between areas with larger and smaller changes.");
  add(se,`The collection of observations from ${c.place} _____ available to the research team.`,"Which choice completes the text according to Standard English conventions?","is",["are","have been","were"],"The subject is singular 'collection', not plural 'observations'.");
  add(se,`Last year, researchers _____ ${c.object} at ${c.place}; the records were completed before winter.`,"Which choice completes the text according to Standard English conventions?","examined",["examine","will examine","are examining"],"'Last year' and the completed records require the simple past.");
  add(se,`The researchers had one immediate goal _____ they would repeat the measurements at ${c.place}.`,"Which choice completes the text according to Standard English conventions?",";",[",","; and,",", and,"],"Both sides are independent clauses. A semicolon joins them without a comma splice or an incorrectly punctuated conjunction.");
  add(se,`The team at ${c.place} recorded the results carefully. _____ later shared the records with another laboratory.`,"Which choice completes the text according to Standard English conventions?","It",["Them","Its","Theirs"],"'It' is the subject pronoun referring to the singular collective noun 'team'.");
  add(se,`Neither the director nor the two assistants _____ willing to discard the incomplete records from ${c.place}.`,"Which choice completes the text according to Standard English conventions?","were",["was","is","has been"],"With neither/nor, the verb agrees with the nearer subject, plural 'assistants'.");
  add(se,`To investigate ${c.measure}, _____ compared repeated observations from ${c.place}.`,"Which choice completes the text according to Standard English conventions?","the researchers",["the results","the explanation","the measurements"],"The introductory purpose phrase must modify the people doing the investigation; the other choices create illogical agents.");
  add(se,`The report from ${c.place} had been checked by three researchers _____ several uncertainty estimates still needed revision.`,"Which choice completes the text according to Standard English conventions?","; however,",[", however,"," however;",", however;"],"Two independent clauses require a semicolon before the conjunctive adverb; a comma follows it.");
  add(ec,`${cap(c.intervention)} was expected to increase ${c.measure}. _____ the initial trial at ${c.place} produced little measurable change.`,"Which transition most logically completes the text?","However,",["Similarly,","For example,","Therefore,"],"The trial contrasts with the expectation.");
  add(ec,`The team at ${c.place} discovered gaps in the observation log. _____ it could not calculate a reliable weekly average.`,"Which transition most logically completes the text?","Consequently,",["Nevertheless,","Likewise,","For instance,"],"The missing data cause the inability to calculate a reliable average.");
  add(ec,`Notes:\n• Location: ${c.place}.\n• Study objects: ${c.object}.\n• Intervention: ${c.intervention}.\n• Intended benefit: ${c.benefit}.`,"The student wants to identify the intervention and its purpose. Which choice best uses the notes?",`At ${c.place}, ${c.intervention} was studied as a way to achieve ${c.benefit}.`,[`${c.place} was the location of a study.`,`At ${c.place}, ${c.subject} studied ${c.object} and recorded several kinds of observations about them.`,`The notes identify both a location and some objects.`],"Only the correct option states both what was changed and why.");
  add(ec,`Notes:\n• One trial found increased ${c.measure}.\n• ${cap(c.limitation)}.\n• No comparable untreated units were observed.`,"The student wants to explain why a causal claim would be premature. Which choice best uses the notes?","Without untreated comparisons, the observed increase could reflect background changes rather than the intervention alone.",["Because the increase was observed after the intervention began, the intervention must have produced all of it.","The study has no possible practical relevance.","The intervention was tested in every possible setting."],"The answer connects the lack of controls to the alternative explanation.");
  add(ec,`The investigators collected more than the final totals from ${c.place}. _____ they recorded the conditions and methods used for each observation.`,"Which transition most logically completes the text?","In addition,",["In contrast,","Even so,","Instead,"],"Recording conditions adds another type of information; it does not replace or contradict totals.");
  add(ec,`A first report described ${c.measure} at ${c.place}. A follow-up used the same methods but covered two seasons rather than one.`,"Which sentence best emphasises the extension in the follow-up?","Using comparable methods, the follow-up broadened the observation period to two seasons.",["The first report and follow-up have nothing in common.","The follow-up repeated the first report's single season using different methods at a new site.","Both reports prove that seasonal differences never matter."],"The answer preserves methodological continuity while highlighting the longer period.");
}

/** Module 2, lower route: new items at a moderate level, none repeating Module 1. */
function lowerReading(c: Context, paper: number, add: Add) {
  add(cs,`${cap(c.subject)} called its first count of ${c.measure} at ${c.place} "preliminary": the members planned to count again once ${c.intervention} had been in place for a full season.`,"As used in the text, 'preliminary' most nearly means","early and incomplete",["carefully kept secret","final and fully certain","too costly to repeat"],"The members planned another count, so the first one came early and was not the full picture.");
  add(cs,`The rise in ${c.measure} after ${c.intervention} proved robust: it appeared in every count that ${c.subject} made at ${c.place}, not only in the first one.`,"As used in the text, 'robust' most nearly means","consistent across checks",["physically heavy and strong","argued for with great energy","difficult to measure again"],"The rise appeared in every count, so it held up when checked again.");
  add(cs,`${cap(c.subject)} first describes how it began ${c.intervention} at ${c.place}. It then reports that ${c.measure} rose afterward. Finally, it notes that ${c.limitation}.`,"Which choice best describes the overall structure of the text?","A change is described, a result is reported, and a complication is noted.",["A claim is made, tested, and then rejected as completely false.","Two places are compared in detail, and the better place is recommended for every future study.","A problem is described, and several unrelated solutions are listed."],"The text moves from the change, to the result, to a limitation.");
  add(cs,`The members of ${c.subject} were pleased that ${c.measure} rose after ${c.intervention}. They did not, however, credit the change alone, because ${c.limitation}.`,"Which choice best describes the function of the second sentence in the text?","It explains why the members were cautious about what caused the rise.",["It describes how the members first chose the change they made.","It shows that the members rejected the change as a failure.","It reports that the rise was larger than anyone had expected it to be."],"'However' introduces the members' caution and the reason for it.");
  add(cs,`Text 1: Supporters of ${c.intervention} say it will bring ${c.benefit}.\nText 2: At ${c.place}, ${c.measure} did improve after ${c.intervention}, but ${c.limitation}. One good result is not proof.`,"Based on the texts, how would the author of Text 2 most likely respond to the supporters in Text 1?","By agreeing that the change may help while warning that one result is weak evidence",["By arguing that the result at a single place has already proven the change works at every other site","By claiming that the change made the measured outcome noticeably worse","By suggesting that no further measurements at any site would be useful"],"Text 2 accepts the improvement but says a single result does not prove the claim.");
  add(cs,`This short report from ${c.place} explains how ${c.subject} recorded ${c.measure} each week, both before and after ${c.intervention}, so that the two periods could be compared.`,"Which choice best states the main purpose of the text?","To describe how a comparison was set up",["To argue that the change failed everywhere","To explain the long history of the location","To praise one member for doing most of the work"],"The report explains the weekly records kept before and after the change.");
  add(cs,`Because ${c.limitation}, ${c.subject} offered only a tentative explanation for the change in ${c.measure} at ${c.place}.`,"As used in the text, 'tentative' most nearly means","not yet certain",["fully proven by tests","openly hostile to others","easily heard by everyone"],"The limitation keeps the explanation from being certain.");
  const week1=10+paper*2, week4=week1+6;
  add(ii,`${cap(c.subject)} recorded ${c.measure} at ${c.place}. In the first week after ${c.intervention}, the count was ${week1}; in the fourth week, it was ${week4}.`,"Which choice most accurately describes the data in the text?",`The count rose by ${week4-week1} between the first and fourth weeks.`,[`The count fell by ${week4-week1} between the first and fourth weeks.`,`The count stayed at ${week1} throughout the four weeks.`,"The count doubled between the first and fourth weeks."],`${week4} − ${week1} = ${week4-week1}; ${week4} is not twice ${week1}.`);
  add(ii,`${cap(c.subject)} claims that ${c.intervention} improved ${c.measure} at ${c.place}.`,"Which finding, if true, would most directly support the claim?","Areas with the change improved, while similar areas without it did not.",["The members spent a great deal of time planning the change before they began any counts.","The change cost less than the members had expected at the start.","Areas without the change improved just as much as areas with it."],"A difference between otherwise similar areas with and without the change points to the change.");
  add(ii,`Members of ${c.subject} concluded that ${c.intervention} was responsible for the rise in ${c.measure} at ${c.place}.`,"Which finding, if true, would most directly weaken the members' conclusion?","Similar places without the change showed the same rise over the same period.",["The rise continued for several weeks after the change was first made.","The members counted at the same times each week and checked one another's records for errors.","Places with the change showed a larger rise than places without it."],"If places without the change rose just as much, something else may explain the rise.");
  add(ii,`After ${c.intervention}, ${c.measure} increased at ${c.place}. A nearby place where nothing was changed showed almost exactly the same increase.`,"Which choice most reasonably follows from the text?","Something other than the change may account for the increase.",["The change produced the whole increase, including the increase at the nearby place.","The nearby place must have been counted incorrectly.","The increase at the nearby place will soon disappear."],"The same increase without the change suggests another cause.");
  add(ii,`${cap(c.subject)} did not report a single number. Instead, it gave the result for each part of ${c.place}, because ${c.measure} rose sharply in some parts and hardly at all in others.`,"Which choice best states the main idea of the text?","The results differed from one part of the place to another.",["The members reported one overall number because every part of the place rose by the same amount.","No part of the place showed any rise at all.","The members chose not to count any part of the place."],"The text stresses that the rise varied by part of the place.");
  add(ii,`${cap(c.subject)} repeated its count at ${c.place} two weeks later. The members wanted to know whether the first result had been a one-time event or a lasting change.`,"According to the text, why did the members repeat the count?","To check whether the first result would last",["To find out who had made the first count","To show that the first count had been lost","To compare the place with a different town that had already finished its own study"],"The text says the members wanted to know whether the change was lasting.");
  const pre=20+paper, post=pre+2*paper;
  add(ii,`${cap(c.subject)} predicted that ${c.measure} would rise after ${c.intervention}. Before the change, the average was ${pre}; afterward, it was ${post}.`,"Which choice best describes how the data relate to the prediction?","They support it, because the average went up after the change.",["They weaken it, because the average went down after the change.","They neither support nor weaken it, because the average stayed the same.","They support it, because the average was the same before and after."],`The average rose from ${pre} to ${post}, as predicted.`);
  add(se,`The results from every count at ${c.place} _____ shared with the public.`,conventions,"were",["was","is","has been"],"The subject is the plural 'results', not 'count', so the plural verb is needed.");
  add(se,`When the members finished counting at ${c.place}, _____ compared the totals with last year's.`,conventions,"they",["it","them","their"],"The clause needs a plural subject pronoun referring to 'the members'.");
  add(se,`By the end of the season, the members _____ ${c.measure} every week for three months.`,conventions,"had recorded",["will record","record","are recording"],"'By the end of the season' looks back from a past point, so the past perfect is needed.");
  add(se,`The members measured three things at ${c.place} _____ ${c.measure}, rainfall, and temperature.`,conventions,":",[";",",","."],"A colon introduces the list that explains 'three things'.");
  add(se,`The five _____ notebooks, one for each member, held every weekly count from ${c.place}.`,conventions,"members'",["member's","members","members's"],"Five members own the notebooks, so the plural possessive 'members'' is needed.");
  add(se,`${cap(c.measure)} rose in the spring _____ it fell again in the summer.`,conventions,", but",[","," but,","; but,"],"A comma and the conjunction 'but' join the two independent clauses.");
  add(se,`Working slowly through the ${c.object} at ${c.place}, _____.`,conventions,"the members recorded every change they noticed",["every change was recorded by the members","the record of changes grew longer each week",`the ${c.object} were checked one by one`],"The introductory phrase must describe the people doing the work: the members.");
  add(ec,`${cap(c.intervention)} was expected to raise ${c.measure} quickly. _____ the first month showed almost no change.`,transition,"However,",["Therefore,","Similarly,","For instance,"],"The first month contrasts with the expectation.");
  add(ec,`The members kept careful records at ${c.place}. _____ they noted the weather on every visit.`,transition,"For example,",["However,","Instead,","Nevertheless,"],"Noting the weather is an example of careful record keeping.");
  add(ec,`${cap(c.limitation)}. _____ the members decided to repeat the comparison the following year.`,transition,"As a result,",["In contrast,","For example,","Even so,"],"The complication is the reason for repeating the comparison.");
  add(ec,`Notes:\n• Place: ${c.place}\n• Change: ${c.intervention}\n• Aim: ${c.benefit}\n• Measure: ${c.measure}`,notesPrompt("state the aim of the change"),`At ${c.place}, ${c.intervention} was meant to bring ${c.benefit}.`,[`At ${c.place}, the members measured ${c.measure} each week.`,`The study took place at ${c.place}, where a change was made.`,"The notes describe a place, a change, an aim, and a measure."],"Only this choice states the change and its aim.");
  add(ec,`Notes:\n• Result: ${c.measure} rose after ${c.intervention}\n• Problem: ${c.limitation}`,notesPrompt("present the result and explain why it should be treated with caution"),`${cap(c.measure)} rose after ${c.intervention}, but ${c.limitation}, so the result needs caution.`,[`${cap(c.measure)} rose after ${c.intervention}, which proves that the change worked.`,`${cap(c.limitation)}, which is why the study took place.`,`${cap(c.intervention)} was tried at a place where ${c.measure} was measured.`],"Only this choice gives both the result and the reason for caution.");
  add(ec,`First, the members chose sites at ${c.place}. Next, they recorded ${c.measure} for a month. _____ they compared the counts with last year's.`,transition,"Finally,",["For example,","In contrast,","Similarly,"],"The comparison is the last step in the sequence.");
}

/** Module 2, higher route: new, harder items (nuanced inference, evidence and grammar), none repeating Module 1. */
function higherReading(c: Context, paper: number, add: Add) {
  add(cs,`Comparisons between treated and untreated ${c.object} at ${c.place} were confounded by the fact that ${c.limitation}.`,"As used in the text, 'confounded' most nearly means","made hard to interpret",["completely prevented","shown to be entirely accurate","kept hidden from the public"],"A pre-existing difference makes the comparison hard to interpret, though it can still be made.");
  add(cs,`The team's enthusiasm about ${c.benefit} was tempered by its awareness that ${c.limitation}.`,"As used in the text, 'tempered' most nearly means","moderated",["strengthened","heated","concealed"],"Awareness of the limitation makes the enthusiasm less extreme.");
  add(cs,`Many assume that ${c.intervention} reliably improves ${c.measure}. At ${c.place}, however, ${c.subject} found large gains in some ${c.object} and none in others. The team now claims only that the effect depends on local conditions.`,"Which choice best describes the overall structure of the text?","It presents a common assumption, reports findings that complicate it, and states a narrower claim.",["It presents a common assumption, reports findings that confirm it, and extends it to all settings.","It describes a new method, explains why it failed, and recommends abandoning the topic entirely.","It compares two competing theories and argues that both are equally supported by the evidence."],"The uneven results complicate the assumption, and the team narrows its claim.");
  add(cs,`${cap(c.subject)} described its result at ${c.place} as "a promising lead rather than a verdict."`,"The quoted phrase mainly serves to","signal that the result calls for further testing",["indicate that the team considers the result to be fully and finally proved","suggest that the result was reached by chance","imply that the team disagreed about the method"],"A lead is something to follow up; a verdict would be final.");
  add(cs,`Text 1: Gains in ${c.measure} at ${c.place} show that ${c.intervention} works.\nText 2: The gains in ${c.measure} are real, but because ${c.limitation}, they cannot yet be attributed to ${c.intervention}.`,"Based on the texts, how would the author of Text 2 most likely respond to the claim in Text 1?","By accepting the observation but disputing the explanation offered for it",["By rejecting both the observation and the explanation as unsupported","By accepting both the observation and the explanation without reservation","By disputing the observation but accepting the explanation offered for it"],"Text 2 calls the gains real but says their cause is not yet established.");
  add(cs,`${cap(c.subject)} reported higher ${c.measure} after ${c.intervention}. The report also mentions that ${c.limitation}.`,"The report most likely mentions this detail in order to","explain why a simple causal conclusion would be premature",["show that the intervention was applied incorrectly","suggest that the measure was recorded inaccurately","argue that the intervention should now be adopted at every comparable site"],"The detail offers another possible cause of the higher values.");
  add(cs,`A second team later corroborated the finding by measuring ${c.measure} at ${c.place} with an entirely different instrument.`,"As used in the text, 'corroborated' most nearly means","independently confirmed",["publicly challenged in print","only briefly described","carelessly measured"],"A different instrument reaching the same result confirms the finding independently.");
  const treated=12+paper, untreated=4+paper;
  add(ii,`Over one season, ${c.measure} rose by ${treated}% in treated ${c.object} and by ${untreated}% in comparable untreated ${c.object} at ${c.place}.`,"Which conclusion about the data is most strongly supported?",`The treated units rose ${treated-untreated} percentage points more than the untreated units.`,[`The treated units rose ${treated}% because of the intervention alone.`,"The untreated units did not change at all during the season.",`The treated units rose ${treated+untreated} percentage points more than the untreated units.`],`${treated} − ${untreated} = ${treated-untreated}. The untreated units also rose, so not all of the ${treated}% can be credited to the change.`);
  add(ii,`${cap(c.subject)} proposes that ${c.intervention} improves ${c.measure} at ${c.place}, and that larger doses of the change should produce larger gains.`,"Which finding, if true, would most directly support the proposal?","Units that received more of the change showed proportionally larger gains.",["Units that received more of the change showed the same gains as others.","Units without the change showed larger gains than units with it.","The team chose the units that would receive the change by hand."],"Gains that grow with the dose support both parts of the proposal.");
  add(ii,`Researchers who knew which ${c.object} had received ${c.intervention} rated ${c.measure} higher in those units.`,"Which finding, if true, would most seriously weaken the conclusion that the intervention caused the higher ratings?","The difference disappeared when raters did not know which units were treated.",["The difference grew when the same raters measured the units a second time.","The treated units were measured on the same days as the untreated units.","The raters had several years of experience with similar measurements."],"If the difference vanishes when raters are unaware of treatment, the raters' expectations may have produced it.");
  add(ii,`Because ${c.limitation}, ${c.subject} compared each of the ${c.object} at ${c.place} with its own earlier measurements rather than with other units.`,"Which choice best explains why the team made this choice?","To reduce the influence of differences that existed before the study",["To ensure that every unit received the intervention at the same time","To avoid having to measure any unit more than once during the study","To make the results look larger than a standard comparison would"],"Comparing each unit with itself removes differences that existed between units beforehand.");
  add(ii,`If ${c.intervention} truly improves ${c.measure}, the effect should not depend on where a unit started. Thus, if the hypothesis is correct, _____`,"Which choice most logically completes the text?","units with low initial values should still improve after the change.",["only units with high initial values should improve after the change.","no unit should change at all, whatever its initial value.","units should improve before the change has even been made."],"An effect that does not depend on the starting point should appear in low-starting units too.");
  add(ii,`${cap(c.subject)} found that ${c.intervention} improved ${c.measure} at ${c.place} in one season. The team cautioned that a single season at a single location cannot show whether the improvement would last or appear elsewhere.`,"Which choice best states the main idea of the text?","An observed improvement may not generalise beyond the conditions studied.",["An observed improvement has been shown to last and to appear elsewhere.","The team rejected the improvement because it occurred in only one season.","The location studied is unusual, so the measure there is meaningless."],"The caution concerns how far the result can be extended.");
  add(ii,`At ${c.place}, treated ${c.object} rose from ${40+paper} to ${50+paper} on a scale of ${c.measure}, while untreated ones rose from ${30+paper} to ${40+paper}.`,"Which choice best describes what the data suggest?","Both groups rose by the same amount, so the rise may not be due to the change.",["The treated group ended with higher values, so the change clearly caused the entire rise.","The untreated group rose more, so the change slowed the rise.","Neither group changed, so the measure was not recorded properly."],"Each group rose by 10; the treated group was already higher at the start.");
  add(se,`Among the most informative results from ${c.place} _____ the measurements taken immediately after the storm.`,conventions,"were",["was","is","has been"],"The sentence is inverted; its subject is the plural 'measurements', so the plural verb is needed.");
  add(se,`The team's main measure—${c.measure}_____ improved at every site after ${c.intervention}.`,conventions,"—",[",",";",":"],"A phrase opened with a dash must be closed with a dash.");
  add(se,`Neither the director nor the volunteers kept _____ notes after the final visit to ${c.place}.`,conventions,"their",["his or her","its","they're"],"With neither … nor, the pronoun agrees with the nearer antecedent, the plural 'volunteers'.");
  add(se,`The records, _____ after each visit, made later comparisons possible.`,conventions,"updated",["were updated","updating","to update"],"A past participle phrase describes the records without adding a second main verb.");
  add(se,`The team set out to measure ${c.measure}, to record conditions at ${c.place}, and _____.`,conventions,"to compare the results with earlier years",["comparing the results with earlier years","the results were compared with earlier years","compared the results with earlier years"],"Items in a series keep the same form: to measure, to record, and to compare.");
  add(se,`The ${c.object} _____ received the change were chosen at random.`,conventions,"that",[", which","who",", that"],"The clause identifies which units are meant, so it is restrictive: 'that' with no commas.");
  add(se,`The two _____ reports on ${c.place} agreed on every point.`,conventions,"teams'",["team's","teams","teams's"],"Two teams own the reports, so the plural possessive 'teams'' is needed.");
  add(ec,`The gains at ${c.place} were real. _____ they were too small to justify the cost of ${c.intervention} everywhere.`,transition,"Still,",["Thus,","Indeed,","Likewise,"],"The second sentence concedes a limit to the first.");
  add(ec,`The team changed one feature of its method. _____ it measured every unit at the same time of day.`,transition,"Specifically,",["Nonetheless,","By contrast,","Otherwise,"],"The second sentence specifies which feature changed.");
  add(ec,`Because ${c.limitation}, the first comparison could not isolate the effect of ${c.intervention}. _____ the team designed a second comparison in which units were matched in advance.`,transition,"Accordingly,",["Nevertheless,","Similarly,","In other words,"],"The second comparison is the consequence of the first one's weakness.");
  add(ec,`Notes:\n• Treated ${c.object}: ${c.measure} up ${treated}%\n• Untreated ${c.object}: ${c.measure} up ${untreated}%\n• Location: ${c.place}`,notesPrompt("emphasise the difference between the two groups"),`At ${c.place}, treated ${c.object} gained ${treated}%, far more than the ${untreated}% gained by untreated ones.`,[`At ${c.place}, the researchers studied both treated and untreated ${c.object} over the same period of time.`,`Untreated ${c.object} at ${c.place} gained ${untreated}% over the period.`,`${cap(c.measure)} was one of several measures recorded at ${c.place}.`],"Only this choice sets the two gains side by side and stresses the gap.");
  add(ec,`Notes:\n• Researchers: ${c.subject}\n• Question: whether ${c.intervention} improves ${c.measure}\n• Site: ${c.place}`,notesPrompt("introduce the study to an audience unfamiliar with it"),`At ${c.place}, ${c.subject} studied whether ${c.intervention} improves ${c.measure}.`,["The study asked whether the change improves the measure.",`${cap(c.subject)} is a group of researchers who carry out several different kinds of studies at ${c.place}.`,`Whether ${c.intervention} improves ${c.measure} is a question.`],"Only this choice names who, where and what was asked.");
  add(ec,`Notes:\n• Finding: ${c.measure} improved after ${c.intervention}\n• Limitation: ${c.limitation}\n• Next step: a matched comparison`,notesPrompt("acknowledge a limitation of the finding"),`Although ${c.measure} improved after ${c.intervention}, ${c.limitation}, so a matched comparison is planned.`,[`${cap(c.measure)} improved after ${c.intervention}, and the next step is a matched comparison that will confirm the result.`,"A matched comparison is the next step for the study.",`The study found that ${c.measure} improved after ${c.intervention}.`],"Only this choice states the limitation alongside the finding.");
}

export function additionalReading(paper: number, route: Route): ExamQuestion[] {
  const c = contexts[paper-2][route === "first" ? 0 : route === "lower" ? 1 : 2];
  const questions: ExamQuestion[] = [];
  // Module 1 keeps its original IDs; the rewritten Module 2 banks get new ones (v2), so no saved practice result
  // or published edit made for the old items attaches to different questions.
  const version = route === "first" ? "v1" : "v2";
  const add: Add = (domain, passage, prompt, answer, wrong, explanation) => {
    questions.push(choice(`sat-rw-${paper}-${route}-${questions.length+1}-${version}`,domain,passage,prompt,answer,wrong,explanation));
  };
  if (route === "first") firstReading(c, paper, add);
  else if (route === "lower") lowerReading(c, paper, add);
  else higherReading(c, paper, add);
  return questions.map((q,i)=>({...q,pretest:i===5||i===18}));
}
